import{_ as e,o,c as t,ai as a}from"./chunks/framework.Ai2o9gNv.js";const r="/assets/juejin_1.Blte-Rtm.png",i="/assets/juejin_3.So7tYP2E.png",s="/assets/8c69803fa55bd109d4732cc1af040576.CRKHqs57.jpg",l="/assets/4b589940cb05eb574941433dffc5130d.9CP9b3B_.jpg",g="/assets/3961bb080ca32f58221f67964e6c9673.B90SfXhz.jpg",p="/assets/fba1af772e33d4a1bc66a699ba6a998a.A8OTtISc.jpg",d="/assets/6572db5b38a54c14df66a5c114612451.BLxg9a-r.jpg",c="/assets/d5f68fe74faeef6afc2bd591bbd12fc2.DQnMlprM.jpg",f=JSON.parse('{"title":"Vibe Coding不停歇，移动端 TRAE SOLO 让你用手机也能编程啦","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/Vibe Coding不停歇，移动端 TRAE SOLO 让你用手机也能编程啦/Vibe Coding不停歇，移动端 TRAE SOLO 让你用手机也能编程啦.md","filePath":"AI人工智能/Vibe Coding不停歇，移动端 TRAE SOLO 让你用手机也能编程啦/Vibe Coding不停歇，移动端 TRAE SOLO 让你用手机也能编程啦.md","lastUpdated":1778077487000,"__rawMarkdown":"# Vibe Coding不停歇，移动端 TRAE SOLO 让你用手机也能编程啦\\n\\n> 本文参加稀土掘金 **TRAE SOLO 移动端上线征文** 活动，话题：**#TRAE移动生产力#**\\n\\n最近，稀土掘金社区推出了 **TRAE SOLO 移动端上线 ——「我的第一次移动端 AI 办公」评测征文** 活动，看到活动主题的那一刻，我立刻就想到了自己平时那些\\"人在外面，电脑在工位\\"的尴尬时刻：\\n\\n- 路上突然想到一个 Bug 解法，没法立刻录入代码上下文；\\n- 下班后收到线上告警，身边没电脑，只能干着急；\\n- 出差途中急需修改文件或跑个脚本，电脑不在身边……\\n\\n![掘金征文活动首页](./images/juejin_1.png)\\n\\nTRAE SOLO 移动端正是为了解决这些痛点而生的。它主打三大核心场景：**想法随时下发**（语音/拍照触发 AI）、**无缝延续任务**（手机接力 PC 任务）、**远程操控电脑**（手机调用 PC 算力）。\\n\\n![征文三个方向任选](./images/juejin_3.png)\\n\\n这次征文活动提供了三个体验方向：语音下发任务、远程操控电脑、无缝接力任务。我选择的是 **\\"语音下发任务\\"** 方向，在手机上通过自然语言描述需求，让 Trae 的 SOLO Code 帮我完成一个完整的 Web 应用开发。\\n\\n---\\n\\n## 打开 Trae 移动端，开启 Vibe Coding\\n\\n打开 Trae 移动端，映入眼帘的是简洁干净的主界面。顶部可以在 MTC 和 Code 模式之间切换，底部则有 Cloud、连接 Github、分支等功能入口。界面中间提供了几个快捷入口：帮我搭应用、快速看懂项目、碰撞游戏灵感、脚本编写。\\n\\n![Trae 移动端主界面](./images/8c69803fa55bd109d4732cc1af040576.jpg)\\n\\n说实话，第一次在手机屏幕上看到这种\\"代码开发，从这里开始\\"的提示，我还挺意外的——原来手机上也能进行完整的开发流程？\\n\\n---\\n\\n## 灵感闪现：做一个微信群友人格分析工具\\n\\n当天晚上，我在一个技术群里看到群友们热烈讨论鸿蒙开发、arkUI-x 等话题，大家各抒己见，氛围特别好。看着这些聊天记录，我突然冒出一个想法：**能不能开发一个小工具，上传微信群聊截图，让 AI 分析每个群友的性格特点，并生成可导出的个人画像报告？**\\n\\n![技术群聊天截图，氛围活跃（已打码保护隐私）](./images/4b589940cb05eb574941433dffc5130d.jpg)\\n\\n这个想法让我觉得很有趣，既实用又有娱乐性。于是我立刻打开 Trae 移动端，在输入框中详细描述了我的需求：\\n\\n> \\"帮我开发一个微信群友人格分析工具，可以是在线的 web 形式。我会给你微信群聊截图，你需要识别截图内容，然后分析出不同微信群友的性格特点。而且每个群友的分析报告都可以导出分享。\\"\\n\\n![在 Trae 移动端输入开发需求](./images/3961bb080ca32f58221f67964e6c9673.jpg)\\n\\n---\\n\\n## SOLO Code 接棒，全流程自动开发\\n\\n提交需求后，Trae 的 **SOLO Code** 模式立即启动了。它首先分析了这是一个完整的 Web 应用开发任务，然后开始按部就班地执行：\\n\\n1. **创建需求文档（PRD）和技术架构文档**\\n2. **初始化 React 项目**\\n3. **开发核心功能模块**\\n4. **构建并修复问题**\\n5. **部署上线**\\n\\n![SOLO Code 开始分析并创建文档](./images/fba1af772e33d4a1bc66a699ba6a998a.jpg)\\n\\n整个过程中，SOLO Code 展现了非常专业的开发流程。它不仅完成了需求分析，还主动规划了项目结构、选择了合适的技术栈（React + TypeScript + Vite），并且在开发过程中持续输出进度报告。\\n\\n---\\n\\n## 功能迭代：从开发到修复，一气呵成\\n\\n大约 16 分钟后，SOLO Code 完成了第一版开发，并给出了详细的项目总结：\\n\\n### 已实现的核心功能\\n\\n- **截图上传系统**：支持拖拽上传和点击上传，多图批量上传，实时显示上传进度\\n- **OCR 文字识别**：基于 Tesseract.js 的前端 OCR 识别，自动解析微信群聊格式，提取发言者、时间和内容\\n- **人格分析算法**：\\n  - 活跃度分析（发言频率、时间分布）\\n  - 语言风格分析（词汇、修辞、表情）\\n  - 社交特征分析（互动频率、回复模式）\\n  - 情感倾向分析（积极/消极词汇比例）\\n  - 生成性格雷达图\\n- **报告展示与导出**：群友卡片式展示、详细人格报告页面、可视化雷达图、性格优缺点分析、聊天亮点提取、导出 PNG/PDF、生成分享链接\\n- **精美的 UI 设计**：现代简约风格、卡片式布局和圆角设计、流畅的动画效果、响应式设计（桌面、平板、手机）\\n- **隐私保护**：所有处理在浏览器本地完成，数据不上传服务器\\n\\n![SOLO Code 完成开发并输出详细总结](./images/6572db5b38a54c14df66a5c114612451.jpg)\\n\\n不过，在我进行功能测试时，发现了一个小问题：点击上传截图没有反应。我立即在 Trae 中反馈了这个问题，SOLO Code 快速定位到原因是 CSS 中 `input[type=\\"file\\"]` 被设置了 `display: none`，导致文件选择器被隐藏。随后它修复了样式问题，并重新构建了生产版本，还贴心地提供了 GitHub Pages、Vercel、Netlify 三种部署方案。\\n\\n---\\n\\n## 成果展示：一个像模像样的 Web 应用\\n\\n最终，我在手机上完成了一个功能完整的 **\\"微信群友人格分析\\"** Web 应用。打开预览页面，可以看到精心设计的首页：\\n\\n- 顶部是醒目的标题和工具 Logo\\n- 三个核心卖点卡片：隐私保护（所有处理在本地完成）、AI 智能分析（基于心理学理论，多维度分析性格特征）、快速便捷（上传即可分析，几秒生成专业报告）\\n- 底部是大大的拖拽上传区域，支持 PNG、JPG、JPEG 格式\\n\\n![微信群友人格分析工具 Web 预览](./images/d5f68fe74faeef6afc2bd591bbd12fc2.jpg)\\n\\n整个应用从需求提出到最终可预览，全程在手机上完成，没有开过一次电脑。这种体验真的很奇妙——**原来移动端 Vibe Coding 不是概念，而是真的可以落地的事情。**\\n\\n---\\n\\n## 体验总结\\n\\n这次使用 Trae SOLO 移动端进行开发的体验，让我对\\"移动端 AI 办公\\"有了全新的认识：\\n\\n**1. 打破设备边界**\\n以前总觉得写代码必须要坐在电脑前，现在发现很多开发任务其实可以在手机上发起和完成。Trae 的 SOLO Code 模式把复杂的工程化流程封装得很好，用户只需要描述需求，剩下的交给 AI。\\n\\n**2. 自然语言即代码**\\n整个开发过程中，我没有写一行代码，全部通过自然语言描述需求、反馈问题。AI 不仅能理解意图，还能主动补全上下文、规划技术方案、修复 Bug。这种\\"说人话就能开发\\"的体验，极大降低了开发门槛。\\n\\n**3. 全流程闭环**\\n从需求分析 → 项目初始化 → 代码开发 → Bug 修复 → 构建部署，Trae 在手机上完成了完整的开发闭环。特别是自动修复问题和提供部署方案的功能，让我感受到了 AI 作为\\"结对程序员\\"的价值。\\n\\n**4. 隐私保护到位**\\n这个案例中的\\"本地处理\\"设计让我印象深刻。OCR 识别、人格分析全部在浏览器端完成，聊天记录不会上传到任何服务器，这对于涉及敏感数据的场景非常重要。\\n\\n---\\n\\n## 写在最后\\n\\nTRAE SOLO 移动端的上线，让我看到了未来开发工作的一种新可能：**随时随地，有想法就能动手实现。** 不再需要等待回到电脑前，不再受限于设备和环境，灵感来了，掏出手机就能开始 Vibe Coding。\\n\\n如果你也有\\"人在外面，电脑不在身边\\"的困扰，或者想体验一下在手机上指挥 AI 开发应用的感觉，强烈推荐下载 **TRAE SOLO 移动端** 试一试。说不定你的下一个 side project，就是在通勤路上诞生的呢？\\n\\n拿起手机，写下你的第一篇移动端 AI 办公评测吧！🚀\\n\\n---\\n\\n*活动详情参考：[TRAE SOLO 移动端上线征文｜\\"我的第一次移动端AI办公\\"评测](https://juejin.cn/post/7636583332298948623)*"}'),O={name:"AI人工智能/Vibe Coding不停歇，移动端 TRAE SOLO 让你用手机也能编程啦/Vibe Coding不停歇，移动端 TRAE SOLO 让你用手机也能编程啦.md"};function b(u,n,_,h,T,C){return o(),t("div",null,[...n[0]||(n[0]=[a('<h1 id="vibe-coding不停歇-移动端-trae-solo-让你用手机也能编程啦" tabindex="-1">Vibe Coding不停歇，移动端 TRAE SOLO 让你用手机也能编程啦 <a class="header-anchor" href="#vibe-coding不停歇-移动端-trae-solo-让你用手机也能编程啦" aria-label="Permalink to &quot;Vibe Coding不停歇，移动端 TRAE SOLO 让你用手机也能编程啦&quot;">​</a></h1><blockquote><p>本文参加稀土掘金 <strong>TRAE SOLO 移动端上线征文</strong> 活动，话题：<strong>#TRAE移动生产力#</strong></p></blockquote><p>最近，稀土掘金社区推出了 <strong>TRAE SOLO 移动端上线 ——「我的第一次移动端 AI 办公」评测征文</strong> 活动，看到活动主题的那一刻，我立刻就想到了自己平时那些&quot;人在外面，电脑在工位&quot;的尴尬时刻：</p><ul><li>路上突然想到一个 Bug 解法，没法立刻录入代码上下文；</li><li>下班后收到线上告警，身边没电脑，只能干着急；</li><li>出差途中急需修改文件或跑个脚本，电脑不在身边……</li></ul><p><img src="'+r+'" alt="掘金征文活动首页"></p><p>TRAE SOLO 移动端正是为了解决这些痛点而生的。它主打三大核心场景：<strong>想法随时下发</strong>（语音/拍照触发 AI）、<strong>无缝延续任务</strong>（手机接力 PC 任务）、<strong>远程操控电脑</strong>（手机调用 PC 算力）。</p><p><img src="'+i+'" alt="征文三个方向任选"></p><p>这次征文活动提供了三个体验方向：语音下发任务、远程操控电脑、无缝接力任务。我选择的是 <strong>&quot;语音下发任务&quot;</strong> 方向，在手机上通过自然语言描述需求，让 Trae 的 SOLO Code 帮我完成一个完整的 Web 应用开发。</p><hr><h2 id="打开-trae-移动端-开启-vibe-coding" tabindex="-1">打开 Trae 移动端，开启 Vibe Coding <a class="header-anchor" href="#打开-trae-移动端-开启-vibe-coding" aria-label="Permalink to &quot;打开 Trae 移动端，开启 Vibe Coding&quot;">​</a></h2><p>打开 Trae 移动端，映入眼帘的是简洁干净的主界面。顶部可以在 MTC 和 Code 模式之间切换，底部则有 Cloud、连接 Github、分支等功能入口。界面中间提供了几个快捷入口：帮我搭应用、快速看懂项目、碰撞游戏灵感、脚本编写。</p><p><img src="'+s+'" alt="Trae 移动端主界面"></p><p>说实话，第一次在手机屏幕上看到这种&quot;代码开发，从这里开始&quot;的提示，我还挺意外的——原来手机上也能进行完整的开发流程？</p><hr><h2 id="灵感闪现-做一个微信群友人格分析工具" tabindex="-1">灵感闪现：做一个微信群友人格分析工具 <a class="header-anchor" href="#灵感闪现-做一个微信群友人格分析工具" aria-label="Permalink to &quot;灵感闪现：做一个微信群友人格分析工具&quot;">​</a></h2><p>当天晚上，我在一个技术群里看到群友们热烈讨论鸿蒙开发、arkUI-x 等话题，大家各抒己见，氛围特别好。看着这些聊天记录，我突然冒出一个想法：<strong>能不能开发一个小工具，上传微信群聊截图，让 AI 分析每个群友的性格特点，并生成可导出的个人画像报告？</strong></p><p><img src="'+l+'" alt="技术群聊天截图，氛围活跃（已打码保护隐私）"></p><p>这个想法让我觉得很有趣，既实用又有娱乐性。于是我立刻打开 Trae 移动端，在输入框中详细描述了我的需求：</p><blockquote><p>&quot;帮我开发一个微信群友人格分析工具，可以是在线的 web 形式。我会给你微信群聊截图，你需要识别截图内容，然后分析出不同微信群友的性格特点。而且每个群友的分析报告都可以导出分享。&quot;</p></blockquote><p><img src="'+g+'" alt="在 Trae 移动端输入开发需求"></p><hr><h2 id="solo-code-接棒-全流程自动开发" tabindex="-1">SOLO Code 接棒，全流程自动开发 <a class="header-anchor" href="#solo-code-接棒-全流程自动开发" aria-label="Permalink to &quot;SOLO Code 接棒，全流程自动开发&quot;">​</a></h2><p>提交需求后，Trae 的 <strong>SOLO Code</strong> 模式立即启动了。它首先分析了这是一个完整的 Web 应用开发任务，然后开始按部就班地执行：</p><ol><li><strong>创建需求文档（PRD）和技术架构文档</strong></li><li><strong>初始化 React 项目</strong></li><li><strong>开发核心功能模块</strong></li><li><strong>构建并修复问题</strong></li><li><strong>部署上线</strong></li></ol><p><img src="'+p+'" alt="SOLO Code 开始分析并创建文档"></p><p>整个过程中，SOLO Code 展现了非常专业的开发流程。它不仅完成了需求分析，还主动规划了项目结构、选择了合适的技术栈（React + TypeScript + Vite），并且在开发过程中持续输出进度报告。</p><hr><h2 id="功能迭代-从开发到修复-一气呵成" tabindex="-1">功能迭代：从开发到修复，一气呵成 <a class="header-anchor" href="#功能迭代-从开发到修复-一气呵成" aria-label="Permalink to &quot;功能迭代：从开发到修复，一气呵成&quot;">​</a></h2><p>大约 16 分钟后，SOLO Code 完成了第一版开发，并给出了详细的项目总结：</p><h3 id="已实现的核心功能" tabindex="-1">已实现的核心功能 <a class="header-anchor" href="#已实现的核心功能" aria-label="Permalink to &quot;已实现的核心功能&quot;">​</a></h3><ul><li><strong>截图上传系统</strong>：支持拖拽上传和点击上传，多图批量上传，实时显示上传进度</li><li><strong>OCR 文字识别</strong>：基于 Tesseract.js 的前端 OCR 识别，自动解析微信群聊格式，提取发言者、时间和内容</li><li><strong>人格分析算法</strong>： <ul><li>活跃度分析（发言频率、时间分布）</li><li>语言风格分析（词汇、修辞、表情）</li><li>社交特征分析（互动频率、回复模式）</li><li>情感倾向分析（积极/消极词汇比例）</li><li>生成性格雷达图</li></ul></li><li><strong>报告展示与导出</strong>：群友卡片式展示、详细人格报告页面、可视化雷达图、性格优缺点分析、聊天亮点提取、导出 PNG/PDF、生成分享链接</li><li><strong>精美的 UI 设计</strong>：现代简约风格、卡片式布局和圆角设计、流畅的动画效果、响应式设计（桌面、平板、手机）</li><li><strong>隐私保护</strong>：所有处理在浏览器本地完成，数据不上传服务器</li></ul><p><img src="'+d+'" alt="SOLO Code 完成开发并输出详细总结"></p><p>不过，在我进行功能测试时，发现了一个小问题：点击上传截图没有反应。我立即在 Trae 中反馈了这个问题，SOLO Code 快速定位到原因是 CSS 中 <code>input[type=&quot;file&quot;]</code> 被设置了 <code>display: none</code>，导致文件选择器被隐藏。随后它修复了样式问题，并重新构建了生产版本，还贴心地提供了 GitHub Pages、Vercel、Netlify 三种部署方案。</p><hr><h2 id="成果展示-一个像模像样的-web-应用" tabindex="-1">成果展示：一个像模像样的 Web 应用 <a class="header-anchor" href="#成果展示-一个像模像样的-web-应用" aria-label="Permalink to &quot;成果展示：一个像模像样的 Web 应用&quot;">​</a></h2><p>最终，我在手机上完成了一个功能完整的 <strong>&quot;微信群友人格分析&quot;</strong> Web 应用。打开预览页面，可以看到精心设计的首页：</p><ul><li>顶部是醒目的标题和工具 Logo</li><li>三个核心卖点卡片：隐私保护（所有处理在本地完成）、AI 智能分析（基于心理学理论，多维度分析性格特征）、快速便捷（上传即可分析，几秒生成专业报告）</li><li>底部是大大的拖拽上传区域，支持 PNG、JPG、JPEG 格式</li></ul><p><img src="'+c+'" alt="微信群友人格分析工具 Web 预览"></p><p>整个应用从需求提出到最终可预览，全程在手机上完成，没有开过一次电脑。这种体验真的很奇妙——<strong>原来移动端 Vibe Coding 不是概念，而是真的可以落地的事情。</strong></p><hr><h2 id="体验总结" tabindex="-1">体验总结 <a class="header-anchor" href="#体验总结" aria-label="Permalink to &quot;体验总结&quot;">​</a></h2><p>这次使用 Trae SOLO 移动端进行开发的体验，让我对&quot;移动端 AI 办公&quot;有了全新的认识：</p><p><strong>1. 打破设备边界</strong> 以前总觉得写代码必须要坐在电脑前，现在发现很多开发任务其实可以在手机上发起和完成。Trae 的 SOLO Code 模式把复杂的工程化流程封装得很好，用户只需要描述需求，剩下的交给 AI。</p><p><strong>2. 自然语言即代码</strong> 整个开发过程中，我没有写一行代码，全部通过自然语言描述需求、反馈问题。AI 不仅能理解意图，还能主动补全上下文、规划技术方案、修复 Bug。这种&quot;说人话就能开发&quot;的体验，极大降低了开发门槛。</p><p><strong>3. 全流程闭环</strong> 从需求分析 → 项目初始化 → 代码开发 → Bug 修复 → 构建部署，Trae 在手机上完成了完整的开发闭环。特别是自动修复问题和提供部署方案的功能，让我感受到了 AI 作为&quot;结对程序员&quot;的价值。</p><p><strong>4. 隐私保护到位</strong> 这个案例中的&quot;本地处理&quot;设计让我印象深刻。OCR 识别、人格分析全部在浏览器端完成，聊天记录不会上传到任何服务器，这对于涉及敏感数据的场景非常重要。</p><hr><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>TRAE SOLO 移动端的上线，让我看到了未来开发工作的一种新可能：<strong>随时随地，有想法就能动手实现。</strong> 不再需要等待回到电脑前，不再受限于设备和环境，灵感来了，掏出手机就能开始 Vibe Coding。</p><p>如果你也有&quot;人在外面，电脑不在身边&quot;的困扰，或者想体验一下在手机上指挥 AI 开发应用的感觉，强烈推荐下载 <strong>TRAE SOLO 移动端</strong> 试一试。说不定你的下一个 side project，就是在通勤路上诞生的呢？</p><p>拿起手机，写下你的第一篇移动端 AI 办公评测吧！🚀</p><hr><p><em>活动详情参考：<a href="https://juejin.cn/post/7636583332298948623" target="_blank" rel="noreferrer">TRAE SOLO 移动端上线征文｜&quot;我的第一次移动端AI办公&quot;评测</a></em></p>',53)])])}const A=e(O,[["render",b]]);export{f as __pageData,A as default};
